fn solve(n: i8) -> Vec<char> {
    // We use only 'a' and 'b' and enforce s[i] != s[i+2] by repeating the
    // 4‐character pattern "abba".
    let mut result = Vec::with_capacity(n as usize);
    // Pattern of length 4 which satisfies s[i] != s[i+2]
    let pattern = ['a', 'b', 'b', 'a'];
    for i in 0..(n as usize) {
        result.push(pattern[i % 4]);
    }
    result
}

fn main() {
    // Quick tests
    assert_eq!(solve(1), vec!['a']);
    assert_eq!(solve(2), vec!['a', 'b']);
    assert_eq!(solve(3), vec!['a', 'b', 'b']);
    assert_eq!(solve(4), vec!['a', 'b', 'b', 'a']);
    assert_eq!(solve(5), vec!['a', 'b', 'b', 'a', 'a']);
    assert_eq!(solve(6), vec!['a', 'b', 'b', 'a', 'a', 'b']);
    // Check the constraint s[i] != s[i+2]
    let s = solve(10);
    for i in 0..s.len().saturating_sub(2) {
        assert!(s[i] != s[i+2]);
    }
    println!("All tests passed.");
}